from fractions import Fraction as Q
from math import factorial,comb
def moment(p,n,a):return Q(0) if n%p else Q(factorial(n),factorial(n//p))*a**(n//p)
def fall(n,r):return 0 if r>n else factorial(n)//factorial(n-r)
def weighted_mixed_integral(p,d,l,k,a):
    if l<0:return Q(0)
    ans=Q(0)
    for j in range(l+1):
        if (d+j)%p or (l-j)%p:continue
        A=(d+j)//p;B=(l-j)//p
        ans+=comb(l,j)*Q(factorial(d+j),factorial(A))*Q(factorial(l-j),factorial(B))*a**(A+B)*Q(factorial(A)*factorial(B+k),factorial(A+B+k+1))
    return ans
tests=0;examples=[]
for m in range(1,5):
    p=2*m
    for T in [Q(1),Q(1,2),Q(2),Q(5,7)]:
        a=(-1)**(m+1)*T
        for N in range(13):
            for g in range(17):
                channels=[]
                for q in range(1,p):
                    I=Q(0)
                    if N>=q and g>=p-q:
                        n=N-q
                        I=comb(N,q)*p*a*fall(p-1,q-1)*fall(g,p-q)*sum(
                            Q(factorial(n),factorial(k)*factorial(n-p*k))*a**k*
                            weighted_mixed_integral(p,n-p*k,g-p+q,k,a)
                            for k in range(n//p+1))
                    channels.append(I)
                expected=moment(p,N+g,a)-moment(p,N,a)*moment(p,g,a)
                assert sum(channels)==expected,(p,N,g,T,channels,expected)
                if T==1 and (p,N,g) in [(4,3,1),(4,8,4),(6,5,1),(8,7,1),(2,4,4)]:
                    examples.append(dict(p=p,N=N,probe=g,channels=list(map(str,channels)),centered_total=str(expected)))
                tests+=1
print(dict(passed=True,exact_canonical_reconstruction_tests=tests,examples=examples,
           scope='Independent exact signed moments and beta integrals for actual backward Appell canonical fields; '
                 'p=2,4,6,8,degrees0..12,probes0..16,four horizons. No arbitrary completed observable extension inferred.'))
